# 위도 원 — 남극점(0,0)을 중심으로 한 원이라 돌려도 그대로다. 반지름은 EPSG:3031
# 의 ρ(km). 틀 안에 걸리는 것만 — 70°S(2194)는 위로, 82°S(871)는 아래로 벗어난다.
# 이름은 원이 180° 자오선(x = 0)을 지나는 자리에 붙인다.
LAT_CIRCLES = [
    ("72°S", 1971),
    ("74°S", 1749),
    ("76°S", 1528),
    ("78°S", 1308),
    ("80°S", 1089),
]

# 경도 살 — 남극점에서 뻗는 직선. 이 좌표에서 경도 λ 의 방향은 (−sin λ, cos λ)
# 라 180° 가 위로 곧게 선다. 틀보다 넉넉히 길게 긋고 clipPath 가 자른다.
# (이름, 끝점 x, 끝점 y, 이름 x, 이름 y) — 이름은 살이 틀의 위쪽 변(y = −2150)
# 을 지나는 자리다. 160°E·150°W 는 위쪽 변 밖에서 지나 옆 변에 붙인다.
LON_SPOKES = [
    ("160°E", -1094, -3006, -650, -1787),
    ("170°E", -556, -3151, -379, -2150),
    ("180°", 0, -3200, 0, -2150),
    ("170°W", 556, -3151, 379, -2150),
    ("160°W", 1094, -3006, 782, -2150),
    ("150°W", 1600, -2771, 850, -1472),
]

# 바다·땅 이름. 마커 아래에 깔리는 큰 글자 — 자리는 대략이다.
